using Astronomy.MediaFactory.Core.AstronomyDomain.Taxonomy; using Astronomy.MediaFactory.Core.AstronomyDomain.Validation;
namespace Astronomy.MediaFactory.Core.AstronomyDomain.Relationships;
public enum AstronomyRelationshipType { Contains, PartOf, LocatedIn, NeighborOf, AssociatedWith, ParticipatesIn, HostOf, Orbits, OrbitedBy, RadiantLocatedIn, AppearsNear, HistoricallyAssociatedWith, CulturallyAssociatedWith, ObservedWith, DiscoveredBy, NamedAfter, RelatedScientificConcept, Precedes, Follows }
public enum RelationshipDirection { Directed, Bidirectional }
public sealed record AstronomyRelationship(string RelationshipId,string SourceEntityId,string TargetEntityId,AstronomyRelationshipType RelationshipType,RelationshipDirection Direction=RelationshipDirection.Directed,double Confidence=1,IReadOnlyList<string>? SourceIds=null,DateTimeOffset? ValidFrom=null,DateTimeOffset? ValidTo=null,string? Notes=null,IReadOnlyDictionary<string,object?>? Metadata=null){ public IReadOnlyList<string> SourceIds{get;init;}=SourceIds??[]; public IReadOnlyDictionary<string,object?> Metadata{get;init;}=Metadata??new Dictionary<string,object?>(); }
