public sealed class AstronomyRelationshipPolicy:IAstronomyRelationshipPolicy{private static readonly HashSet<AstronomyRelationshipType> Symmetric=[AstronomyRelationshipType.NeighborOf,AstronomyRelationshipType.AssociatedWith,AstronomyRelationshipType.AppearsNear,AstronomyRelationshipType.HistoricallyAssociatedWith,AstronomyRelationshipType.CulturallyAssociatedWith,AstronomyRelationshipType.RelatedScientificConcept]; public bool AllowsSelfReference(AstronomyRelationshipType type)=>false; public bool AllowsBidirectional(AstronomyRelationshipType type)=>Symmetric.Contains(type); public DomainValidationResult ValidateEntityKinds(AstronomyRelationshipType type,AstronomyEntityKind? s,AstronomyEntityKind? t)=>DomainValidationResult.Success;}
